CREATE TABLE "notification_channels" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "config_json" TEXT NOT NULL DEFAULT '{}', "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" DATETIME NOT NULL);
CREATE TABLE "notification_rules" ("id" TEXT NOT NULL PRIMARY KEY, "channel_id" TEXT NOT NULL, "name" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "event_types" TEXT NOT NULL, "filter_json" TEXT NOT NULL DEFAULT '{}', "template_json" TEXT NOT NULL DEFAULT '{}', "throttle_seconds" INTEGER NOT NULL DEFAULT 0, "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" DATETIME NOT NULL, CONSTRAINT "notification_rules_channel_id_fkey" FOREIGN KEY ("channel_id") REFERENCES "notification_channels" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "notification_deliveries" ("id" TEXT NOT NULL PRIMARY KEY, "channel_id" TEXT NOT NULL, "rule_id" TEXT, "event_id" TEXT, "dedupe_key" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "attempt_count" INTEGER NOT NULL DEFAULT 0, "payload_json" TEXT NOT NULL DEFAULT '{}', "last_error" TEXT, "next_attempt_at" DATETIME, "delivered_at" DATETIME, "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" DATETIME NOT NULL, CONSTRAINT "notification_deliveries_channel_id_fkey" FOREIGN KEY ("channel_id") REFERENCES "notification_channels" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "notification_deliveries_rule_id_fkey" FOREIGN KEY ("rule_id") REFERENCES "notification_rules" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "notification_deliveries_dedupe_key_key" ON "notification_deliveries"("dedupe_key");
CREATE INDEX "notification_deliveries_status_next_attempt_at_idx" ON "notification_deliveries"("status", "next_attempt_at");
CREATE TABLE "approval_requests" ("id" TEXT NOT NULL PRIMARY KEY, "status" TEXT NOT NULL DEFAULT 'pending', "actor_type" TEXT NOT NULL, "actor_id" TEXT NOT NULL, "actor_name" TEXT, "workspace_id" TEXT NOT NULL, "run_id" TEXT, "node_id" TEXT, "capability" TEXT NOT NULL, "operation" TEXT NOT NULL, "resource" TEXT NOT NULL, "risk" TEXT NOT NULL, "reason" TEXT NOT NULL DEFAULT '', "preview_json" TEXT NOT NULL DEFAULT '{}', "protected_action" BOOLEAN NOT NULL DEFAULT false, "policy_version" INTEGER NOT NULL DEFAULT 1, "correlation_id" TEXT NOT NULL, "expires_at" DATETIME NOT NULL, "decided_at" DATETIME, "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "approval_requests_status_expires_at_idx" ON "approval_requests"("status", "expires_at");
CREATE INDEX "approval_requests_run_id_node_id_idx" ON "approval_requests"("run_id", "node_id");
CREATE TABLE "approval_decisions" ("id" TEXT NOT NULL PRIMARY KEY, "request_id" TEXT NOT NULL, "decision" TEXT NOT NULL, "decided_by" TEXT NOT NULL, "note" TEXT NOT NULL DEFAULT '', "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "approval_decisions_request_id_fkey" FOREIGN KEY ("request_id") REFERENCES "approval_requests" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "approval_decisions_request_id_created_at_idx" ON "approval_decisions"("request_id", "created_at");
CREATE TABLE "approval_grants" ("id" TEXT NOT NULL PRIMARY KEY, "actor_id" TEXT NOT NULL, "workspace_id" TEXT NOT NULL, "run_id" TEXT, "capability" TEXT NOT NULL, "resource" TEXT NOT NULL, "policy_version" INTEGER NOT NULL DEFAULT 1, "expires_at" DATETIME, "revoked_at" DATETIME, "created_by" TEXT NOT NULL, "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "approval_grants_actor_id_workspace_id_capability_idx" ON "approval_grants"("actor_id", "workspace_id", "capability");
